'use strict';

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const repoRoot = path.resolve(__dirname, '../../..');
const readingRoom = path.join(repoRoot, 'ChatMachines/GeminiSupervisor/live-ground-truth/reading-room');
const TASK_ID = 'task_semantic_define_each_array_item';
const ACTIVE_RE = new RegExp(`^${TASK_ID}-([0-9a-f]{40})\\.json$`, 'i');
const apiKey = process.env.GEMINI_API_KEY;
const model = process.env.GEMINI_MODEL;
const BATCH_SIZE = Number(process.env.COMPREHENSION_BATCH_SIZE || 24);
const REQUEST_TIMEOUT_MS = Number(process.env.COMPREHENSION_TIMEOUT_MS || 300000);

if (!apiKey) throw new Error('GEMINI_API_KEY is missing');
if (!model) throw new Error('GEMINI_MODEL is missing');

function findActiveTask() {
  const names = fs.readdirSync(readingRoom).filter(name => ACTIVE_RE.test(name));
  if (names.length !== 1) throw new Error(`Expected exactly one active comprehension task; found ${names.length}`);
  return path.join(readingRoom, names[0]);
}

function resolveRepoFile(relativePath) {
  if (typeof relativePath !== 'string' || relativePath.trim() === '') throw new Error('Expected a non-empty repository-relative filename.');
  const resolved = path.resolve(repoRoot, relativePath);
  const prefix = `${repoRoot}${path.sep}`;
  if (resolved !== repoRoot && !resolved.startsWith(prefix)) throw new Error(`Path escapes repository root: ${relativePath}`);
  return resolved;
}

function terminalNode(value) {
  let node = value;
  while (node !== null && typeof node === 'object') {
    if (Array.isArray(node)) {
      if (node.length !== 1) return node;
      node = node[0];
      continue;
    }
    const keys = Object.keys(node);
    if (keys.length !== 1) return node;
    node = node[keys[0]];
  }
  return node;
}

function terminalIsEmptyContainer(value) {
  const terminal = terminalNode(value);
  if (Array.isArray(terminal)) return terminal.length === 0;
  return terminal !== null && typeof terminal === 'object' && Object.keys(terminal).length === 0;
}

function extractJson(text) {
  const trimmed = text.trim();
  try { return JSON.parse(trimmed); } catch (error) {
    const fenced = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
    if (!fenced) throw error;
    return JSON.parse(fenced[1]);
  }
}

async function callGemini(parts, systemInstruction, maxOutputTokens = 32768) {
  const response = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-goog-api-key': apiKey
      },
      body: JSON.stringify({
        system_instruction: { parts: [{ text: systemInstruction }] },
        contents: [{ role: 'user', parts }],
        generationConfig: {
          temperature: 0,
          responseMimeType: 'application/json',
          maxOutputTokens
        }
      }),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS)
    }
  );

  const raw = await response.text();
  let body;
  try { body = JSON.parse(raw); } catch (_) {
    throw new Error(`Gemini returned non-JSON HTTP ${response.status}: ${raw.slice(0, 2000)}`);
  }
  if (!response.ok) throw new Error(`Gemini HTTP ${response.status}: ${JSON.stringify(body.error || body)}`);
  const reply = body.candidates?.[0]?.content?.parts?.map(part => part.text || '').join('\n').trim();
  if (!reply) throw new Error(`Gemini returned no text: ${JSON.stringify(body).slice(0, 4000)}`);
  return extractJson(reply);
}

function validDefinitionArray(value, expectedLength) {
  return Array.isArray(value) && value.length === expectedLength && value.every(record => {
    if (record === null || typeof record !== 'object' || Array.isArray(record)) return false;
    const keys = Object.keys(record);
    return keys.length === 1 && keys[0] === 'item' && typeof record.item === 'string' && record.item.trim() !== '';
  });
}

async function defineBatch(batch, filename, batchNumber, batchCount) {
  const prompt = [
    `Target filename: ${filename}`,
    `Batch ${batchNumber} of ${batchCount}.`,
    'Each INPUT_SIGNATURE below is one non-empty flattened semantic signature from that JSON array.',
    'For every signature, in the exact supplied order, generate its semantic definition in the context of the target filename.',
    'Define what the signature means in the document/task contract, using its path, field name, and terminal value. Do not merely restate JSON syntax.',
    'Return definition only. Each output record must have exactly one key named item and one non-empty string value.',
    `Return JSON only as an array of exactly ${batch.length} records: [{"item":"semantic definition"}, ...].`,
    'Do not add source indexes, source values, categories, confidence, gate fields, commentary, or any other keys.',
    '',
    'INPUT_SIGNATURES:',
    JSON.stringify(batch)
  ].join('\n');

  const system = [
    'You are the semantic-definition worker for a comprehension-task test.',
    'The supplied JSON signatures are authoritative input evidence.',
    'A flattened signature encodes a document path and usually a terminal field/value. Explain the semantic role of that exact signature in context.',
    'Output one definition-only record for every supplied signature, preserving order exactly.',
    'Do not omit, merge, reorder, or add records.'
  ].join(' ');

  for (let attempt = 1; attempt <= 3; attempt++) {
    const result = await callGemini([{ text: prompt }], system, 32768);
    if (validDefinitionArray(result, batch.length)) return result;
    console.error(`[comprehension-agent] batch ${batchNumber} shape validation failed, attempt ${attempt}`);
  }
  throw new Error(`Gemini could not return a valid definition-only array for batch ${batchNumber}`);
}

function writeGzip(relativePath, value) {
  const absolute = resolveRepoFile(relativePath);
  fs.mkdirSync(path.dirname(absolute), { recursive: true });
  const bytes = Buffer.from(JSON.stringify(value), 'utf8');
  fs.writeFileSync(absolute, zlib.gzipSync(bytes, { level: 9 }));
}

async function main() {
  const activePath = findActiveTask();
  const task = JSON.parse(fs.readFileSync(activePath, 'utf8'));
  const filename = task?.verify_target_array?.filename;
  const targetPath = resolveRepoFile(filename);
  const source = JSON.parse(fs.readFileSync(targetPath, 'utf8'));
  if (!Array.isArray(source)) throw new Error('Comprehension target must be a top-level JSON array');

  const nonempty = source.filter(item => !terminalIsEmptyContainer(item));
  const expectedCount = nonempty.length;
  const batchCount = Math.ceil(expectedCount / BATCH_SIZE);
  const activeName = path.basename(activePath);
  const commitSha = (activeName.match(ACTIVE_RE) || [])[1];
  if (!commitSha) throw new Error(`Could not derive task instance SHA from ${activeName}`);

  const archiveRoot = `ChatMachines/GeminiSupervisor/live-ground-truth/reading-room/comprehension-task-batches/${commitSha}`;
  const batchArchiveFilenames = [];
  const allRecords = [];

  console.log(`[comprehension-agent] source items=${source.length}; nonempty=${expectedCount}; batches=${batchCount}`);

  for (let offset = 0; offset < expectedCount; offset += BATCH_SIZE) {
    const batchNumber = Math.floor(offset / BATCH_SIZE) + 1;
    const batch = nonempty.slice(offset, offset + BATCH_SIZE);
    console.log(`[comprehension-agent] semantic batch ${batchNumber}/${batchCount} (${batch.length} signatures)`);
    const records = await defineBatch(batch, filename, batchNumber, batchCount);
    allRecords.push(...records);

    const batchRelative = `${archiveRoot}/batch-${String(batchNumber).padStart(4, '0')}.json.gz`;
    writeGzip(batchRelative, records);
    batchArchiveFilenames.push(batchRelative);
  }

  if (!validDefinitionArray(allRecords, expectedCount)) throw new Error('Combined semantic output failed definition-only validation');

  const completeRelative = `${archiveRoot}/complete.json.gz`;
  writeGzip(completeRelative, allRecords);

  task.count_array_nonempty_items.how_many = expectedCount;
  task.doRecord_withReturnSchema.nonempty_items_counted = expectedCount;
  task.doRecord_withReturnSchema.returnSchemaArraySize = expectedCount;
  task.doRecord_withReturnSchema.returnSchemaArray = allRecords;
  task.doRecord_withReturnSchema.batch_archive_filenames = batchArchiveFilenames;
  task.combine_and_send_batch_archives.complete_batch_archive_filename = completeRelative;

  fs.writeFileSync(activePath, `${JSON.stringify(task, null, 2)}\n`, 'utf8');
  console.log(`[comprehension-agent] completed ${expectedCount} definitions; archive=${completeRelative}`);
}

main().catch(error => {
  console.error(`[comprehension-agent] ${error.stack || error.message}`);
  process.exitCode = 1;
});

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { isDeepStrictEqual } = require('util');

const rootDir = path.resolve(__dirname, '../../..');
const supervisorDir = path.join(rootDir, 'ChatMachines/GeminiSupervisor');
const depMapPath = path.join(supervisorDir, 'dependency-map.json');
const runsRoot = path.join(supervisorDir, 'runs');

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function writeJson(filePath, value) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, JSON.stringify(value, null, 2) + '\n', 'utf8');
}

function validateNonce(runNonce) {
  if (typeof runNonce !== 'string' || !/^[A-Za-z0-9_-]+$/.test(runNonce)) {
    throw new Error(`Invalid run_nonce: ${runNonce}`);
  }
  return runNonce;
}

function registryKeys() {
  const map = readJson(depMapPath);
  const registry = map.truth_readable_registry;
  if (!registry || typeof registry !== 'object' || Array.isArray(registry)) {
    throw new Error('dependency-map.json.truth_readable_registry must be an object');
  }
  return Object.keys(registry);
}

function pathsFor(runNonce) {
  const runDir = path.join(runsRoot, validateNonce(runNonce));
  return {
    runDir,
    formPath: path.join(runDir, 'step-0-form.json'),
    lockPath: path.join(runDir, '.step-0-form.lock.json')
  };
}

function generateStep0Form(userRequest, existingNonce = null) {
  const runNonce = validateNonce(existingNonce || `run_${Date.now()}_${crypto.randomBytes(6).toString('hex')}`);
  const { formPath, lockPath } = pathsFor(runNonce);
  if (fs.existsSync(formPath) || fs.existsSync(lockPath)) {
    throw new Error(`Step 0 form already exists for ${runNonce}`);
  }

  const documents = registryKeys();
  const documentSelection = Object.fromEntries(documents.map((docId) => [docId, false]));
  const generatedAt = new Date().toISOString();
  const request = typeof userRequest === 'string' ? userRequest : '';

  const form = {
    start_of_turn: {
      role_required: 'ChatGPT model',
      role_forbidden: 'Gemini model',
      role_completed: '',
      role_verification: {
        method: '',
        evidence: ''
      },
      run_nonce: runNonce,
      user_request: request,
      current_timestamp: generatedAt,
      return_schema_completed_timestamp: '',
      nonce: runNonce,
      task_understanding: '',
      execution_plan: '',
      document_selection: documentSelection,
      return_schema_completed: false
    },
    _form_control: {
      form_version: 1,
      step_number: 0,
      generated_at: generatedAt,
      selectable_document_universe: documents,
      worker_editable_paths: [
        'start_of_turn.role_completed',
        'start_of_turn.role_verification.method',
        'start_of_turn.role_verification.evidence',
        'start_of_turn.return_schema_completed_timestamp',
        'start_of_turn.task_understanding',
        'start_of_turn.execution_plan',
        'start_of_turn.document_selection.*',
        'start_of_turn.return_schema_completed'
      ]
    }
  };

  const lock = {
    form_version: 1,
    step_number: 0,
    run_nonce: runNonce,
    generated_at: generatedAt,
    locked: {
      role_required: form.start_of_turn.role_required,
      role_forbidden: form.start_of_turn.role_forbidden,
      run_nonce: form.start_of_turn.run_nonce,
      user_request: form.start_of_turn.user_request,
      current_timestamp: form.start_of_turn.current_timestamp,
      nonce: form.start_of_turn.nonce,
      selectable_document_universe: documents
    }
  };

  writeJson(formPath, form);
  writeJson(lockPath, lock);
  return { runNonce, formPath, lockPath, form };
}

function validateStep0Form(runNonce) {
  const { formPath, lockPath } = pathsFor(runNonce);
  if (!fs.existsSync(formPath) || !fs.existsSync(lockPath)) {
    throw new Error(`Step 0 form or lock missing for ${runNonce}`);
  }

  const form = readJson(formPath);
  const lock = readJson(lockPath);
  const start = form.start_of_turn;
  if (!start || typeof start !== 'object' || Array.isArray(start)) {
    throw new Error('Step 0 form requires start_of_turn object');
  }

  const expectedLocked = lock.locked;
  const actualLocked = {
    role_required: start.role_required,
    role_forbidden: start.role_forbidden,
    run_nonce: start.run_nonce,
    user_request: start.user_request,
    current_timestamp: start.current_timestamp,
    nonce: start.nonce,
    selectable_document_universe: form?._form_control?.selectable_document_universe
  };
  if (!isDeepStrictEqual(actualLocked, expectedLocked)) {
    throw new Error('Step 0 system-locked fields were modified');
  }

  const expectedDocs = [...expectedLocked.selectable_document_universe].sort();
  const selection = start.document_selection;
  if (!selection || typeof selection !== 'object' || Array.isArray(selection)) {
    throw new Error('start_of_turn.document_selection must be an object');
  }
  const actualDocs = Object.keys(selection).sort();
  if (!isDeepStrictEqual(actualDocs, expectedDocs)) {
    throw new Error('Step 0 document-selection keys changed from the locked document universe');
  }
  for (const [docId, selected] of Object.entries(selection)) {
    if (typeof selected !== 'boolean') throw new Error(`document_selection.${docId} must be boolean`);
  }

  return form;
}

function main() {
  const mode = process.argv[2];
  if (mode === 'validate') {
    validateStep0Form(process.argv[3]);
    console.log(`Step 0 form valid for ${process.argv[3]}`);
    return;
  }
  if (mode === 'generate') {
    const runNonce = process.argv[3] || null;
    const userRequest = process.argv.slice(4).join(' ');
    const result = generateStep0Form(userRequest, runNonce);
    console.log(`Generated Step 0 form for ${result.runNonce}`);
    return;
  }
  throw new Error('Usage: node generate-step-0-form.js [generate <run_nonce> <user request...> | validate <run_nonce>]');
}

if (require.main === module) {
  try {
    main();
  } catch (error) {
    console.error(error.stack || error.message);
    process.exit(1);
  }
}

module.exports = { generateStep0Form, validateStep0Form };

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const sharp = require('sharp');
const { isDeepStrictEqual } = require('util');

const repoRoot = path.resolve(__dirname, '../../..');
const supervisorRoot = path.join(repoRoot, 'ChatMachines/GeminiSupervisor');
const sourcePath = path.join(supervisorRoot, 'Agents.md');
const requestPath = path.join(supervisorRoot, 'live-ground-truth/read-request.json');
const readingRoom = path.join(supervisorRoot, 'live-ground-truth/reading-room');

const DOC_NAME = 'Agents.reader.json';
const VIEWPORT_WIDTH = 1440;
const VIEWPORT_HEIGHT = 900;
const CHARACTER_HEIGHT_PX = 20;
const CONSERVATIVE_CHARACTER_WIDTH_PX = 12;
const PAD_X = 24;
const PAD_Y = 20;
const FONT_SIZE_PX = 20;
const RAW_ROWS = Math.floor((VIEWPORT_HEIGHT - (2 * PAD_Y)) / CHARACTER_HEIGHT_PX);
const ROWS = RAW_ROWS - (RAW_ROWS % 2);
const COLUMNS = Math.floor((VIEWPORT_WIDTH - (2 * PAD_X)) / CONSERVATIVE_CHARACTER_WIDTH_PX);
const CPX = ROWS * COLUMNS;
const INDEX_PREFIX_CHARS = 8;
const CARD_NAME_RE = /^[0-9a-f]{32}\.png$/;
const ACTIVE_RE = /^Agents\.reader\.json-([0-9a-f]{40})$/i;
const manifestRoot = process.env.READING_ROOM_MANIFEST_DIR || path.join(repoRoot, '.live-ground-truth-cache');

function jsonBytes(value) {
  return Buffer.from(JSON.stringify(value), 'utf8');
}

function writeJson(filePath, value) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, jsonBytes(value));
}

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function gitBlobSha(bytes) {
  const header = Buffer.from(`blob ${bytes.length}\0`, 'utf8');
  return crypto.createHash('sha1').update(header).update(bytes).digest('hex');
}

function entryChars(value) {
  return JSON.stringify(value).length + INDEX_PREFIX_CHARS;
}

function splitLineToRenderableItems(text, eol) {
  if (text === '') return [{ type: 'content', text: '', eol }];

  const chunks = [];
  let current = '';
  for (const ch of text) {
    const candidate = current + ch;
    const probe = { type: 'content', text: candidate, eol: '\r\n' };
    if (current && entryChars(probe) > COLUMNS) {
      chunks.push({ type: 'content', text: current, eol: '' });
      current = ch;
    } else {
      current = candidate;
    }
  }
  chunks.push({ type: 'content', text: current, eol });
  return chunks;
}

function projectAgents() {
  const bytes = fs.readFileSync(sourcePath);
  const text = bytes.toString('utf8');
  const items = [];
  const re = /(.*?)(\r\n|\n|\r|$)/g;
  let match;

  while ((match = re.exec(text)) !== null) {
    if (match[0] === '' && re.lastIndex === text.length) break;
    items.push(...splitLineToRenderableItems(match[1], match[2]));
    if (match[2] === '') break;
  }

  // Make the canonical projected array fill complete even-row cards exactly.
  // Splitting preserves document order and bytes: the first fragment has no EOL and
  // the second fragment retains the original EOL. At most ROWS-1 splits are needed.
  const targetItemCount = Math.ceil(items.length / ROWS) * ROWS;
  while (items.length < targetItemCount) {
    let splitIndex = -1;
    let longest = 1;
    for (let i = 0; i < items.length; i++) {
      const length = items[i]?.text?.length || 0;
      if (length > longest) {
        longest = length;
        splitIndex = i;
      }
    }
    if (splitIndex < 0) throw new Error(`Cannot split projected items to ${targetItemCount}`);
    const original = items[splitIndex];
    const midpoint = Math.ceil(original.text.length / 2);
    items.splice(
      splitIndex,
      1,
      { type: 'content', text: original.text.slice(0, midpoint), eol: '' },
      { type: 'content', text: original.text.slice(midpoint), eol: original.eol }
    );
  }

  for (const item of items) {
    if (entryChars(item) > COLUMNS) {
      throw new Error(`Projected item exceeds conservative row width: ${entryChars(item)} > ${COLUMNS}`);
    }
  }

  return {
    doc_id: 'agents',
    canonical_path: 'ChatMachines/GeminiSupervisor/Agents.md',
    source_blob_sha: gitBlobSha(bytes),
    items
  };
}

function validateCommitSha(value) {
  if (!/^[0-9a-f]{40}$/i.test(value || '')) throw new Error(`Invalid commit SHA: ${value}`);
  return value.toLowerCase();
}

function pathsFor(commitSha) {
  const sha = validateCommitSha(commitSha);
  return {
    active: path.join(readingRoom, `${DOC_NAME}-${sha}`),
    failed: path.join(readingRoom, `${DOC_NAME}-${sha}-FAILED`),
    pass: path.join(readingRoom, `${DOC_NAME}-${sha}-PASS`)
  };
}

function randomCardName() {
  return `${crypto.randomBytes(16).toString('hex')}.png`;
}

function shuffle(values) {
  const out = values.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = crypto.randomInt(0, i + 1);
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

function nominalCardCount(values) {
  const totalChars = values.reduce((sum, value) => sum + entryChars(value), 0);
  return Math.max(1, Math.ceil(totalChars / CPX), Math.ceil(values.length / ROWS));
}

function partitionBalanced(values, cardCount, maxItems, costFn = entryChars) {
  const groups = [];
  let cursor = 0;
  const costs = values.map(costFn);
  const suffix = new Array(values.length + 1).fill(0);
  for (let i = values.length - 1; i >= 0; i--) suffix[i] = suffix[i + 1] + costs[i];

  for (let card = 0; card < cardCount; card++) {
    const cardsLeft = cardCount - card;
    const itemsLeft = values.length - cursor;
    if (itemsLeft <= 0) break;

    const minNeededAfter = Math.max(0, cardsLeft - 1);
    const hardMax = Math.min(maxItems, itemsLeft - minNeededAfter);
    const target = suffix[cursor] / cardsLeft;
    const group = [];
    let used = 0;

    while (group.length < hardMax && cursor < values.length) {
      const cost = costs[cursor];
      const mustTake = group.length === 0;
      if (!mustTake && used + cost > target) break;
      group.push(values[cursor]);
      used += cost;
      cursor++;
    }

    if (group.length === 0 && cursor < values.length) group.push(values[cursor++]);
    groups.push(group);
  }

  while (cursor < values.length) {
    const last = groups[groups.length - 1];
    if (!last || last.length >= maxItems) groups.push([]);
    groups[groups.length - 1].push(values[cursor++]);
  }

  return groups;
}

function buildMixedSlots(pairs, orderedParity) {
  const slots = [];
  const placementSlots = [];
  const orderedOnOdd = orderedParity === 'odd';

  for (const pair of pairs) {
    if (orderedOnOdd) {
      slots.push(pair.ordered, pair.shuffled);
      placementSlots.push(false, true);
    } else {
      slots.push(pair.shuffled, pair.ordered);
      placementSlots.push(true, false);
    }
  }

  if (slots.length > ROWS) throw new Error(`Mixed card exceeds ${ROWS} rows`);
  return { slots, placementSlots };
}

function xmlEscape(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function visibleLine(value, index) {
  return `[${index}] ${JSON.stringify(value)}`;
}

function cardSvg(slots) {
  const texts = slots.map((value, row) => {
    const line = visibleLine(value, row);
    if (line.length > COLUMNS) throw new Error(`Rendered row ${row} exceeds conservative width: ${line.length} > ${COLUMNS}`);
    const y = PAD_Y + ((row + 1) * CHARACTER_HEIGHT_PX) - 3;
    return `<text x="${PAD_X}" y="${y}">${xmlEscape(line)}</text>`;
  }).join('');

  return Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${VIEWPORT_WIDTH}" height="${VIEWPORT_HEIGHT}" viewBox="0 0 ${VIEWPORT_WIDTH} ${VIEWPORT_HEIGHT}">` +
    `<rect width="100%" height="100%" fill="white"/>` +
    `<g xml:space="preserve" fill="black" font-family="DejaVu Sans Mono, monospace" font-size="${FONT_SIZE_PX}px">${texts}</g>` +
    `</svg>`,
    'utf8'
  );
}

function sha256(bytes) {
  return crypto.createHash('sha256').update(bytes).digest('hex');
}

function manifestPath(commitSha) {
  return path.join(manifestRoot, `${validateCommitSha(commitSha)}.json`);
}

async function writeCard(slots) {
  const fileName = randomCardName();
  const filePath = path.join(readingRoom, fileName);
  const png = await sharp(cardSvg(slots)).png({ compressionLevel: 9 }).toBuffer();
  fs.writeFileSync(filePath, png);
  return { fileName, pngSha256: sha256(png) };
}

function removeGeneratedCards() {
  if (!fs.existsSync(readingRoom)) return;
  for (const name of fs.readdirSync(readingRoom)) {
    if (CARD_NAME_RE.test(name)) fs.rmSync(path.join(readingRoom, name), { force: true });
  }
}

function removeLegacyCanonical() {
  const legacy = path.join(readingRoom, DOC_NAME);
  if (fs.existsSync(legacy)) fs.rmSync(legacy, { force: true });
}

function removeActiveChallenges() {
  if (!fs.existsSync(readingRoom)) return;
  for (const name of fs.readdirSync(readingRoom)) {
    if (ACTIVE_RE.test(name)) fs.rmSync(path.join(readingRoom, name), { force: true });
  }
}

async function buildChallenge(commitSha) {
  const sha = validateCommitSha(commitSha);
  const full = projectAgents();
  const canonical = full.items;
  const shuffled = shuffle(canonical);

  if (canonical.length % ROWS !== 0) throw new Error('Canonical item count must fill whole ordered cards');
  const referenceCardCount = canonical.length / ROWS;
  const referenceGroups = [];
  for (let i = 0; i < canonical.length; i += ROWS) {
    referenceGroups.push(canonical.slice(i, i + ROWS));
  }

  const pairs = canonical.map((ordered, i) => ({ ordered, shuffled: shuffled[i] }));
  const pairsPerMixedCard = ROWS / 2;
  const mixedCardCount = referenceCardCount * 2;
  const mixedGroups = [];
  for (let i = 0; i < pairs.length; i += pairsPerMixedCard) {
    mixedGroups.push(pairs.slice(i, i + pairsPerMixedCard));
  }
  if (mixedGroups.length !== mixedCardCount) {
    throw new Error(`Expected ${mixedCardCount} mixed cards, got ${mixedGroups.length}`);
  }

  fs.mkdirSync(readingRoom, { recursive: true });
  removeGeneratedCards();
  removeLegacyCanonical();
  removeActiveChallenges();

  const cards = {};

  for (const group of referenceGroups) {
    const { fileName, pngSha256 } = await writeCard(group);
    cards[fileName] = {
      role: 'ordered-reference',
      slots: group,
      placement_slots: Array(group.length).fill(false),
      png_sha256: pngSha256
    };
  }

  for (const group of mixedGroups) {
    const orderedParity = crypto.randomInt(0, 2) === 0 ? 'odd' : 'even';
    const { slots, placementSlots } = buildMixedSlots(group, orderedParity);
    const { fileName, pngSha256 } = await writeCard(slots);
    cards[fileName] = {
      role: 'mixed',
      ordered_parity: orderedParity,
      slots,
      placement_slots: placementSlots,
      png_sha256: pngSha256
    };
  }

  fs.mkdirSync(manifestRoot, { recursive: true });
  writeJson(manifestPath(sha), {
    challenge: 'agents-png-locator-v2',
    challenge_commit_sha: sha,
    source_blob_sha: full.source_blob_sha,
    item_count: canonical.length,
    logical_copies: { ordered: 2, shuffled: 1 },
    cards
  });

  const challenge = {
    challenge: 'agents-png-locator-v2',
    source_blob_sha: full.source_blob_sha,
    handshake: {
      protocol: 'This challenge is a handshake. Issuing the challenge is the request leg; committing a completed locator is the response leg; a verifier PASS is the acknowledgement that closes the handshake.',
      no_end_of_turn: 'Do not end the turn while this handshake remains open. Continue the read, solve, submit, and evaluate sequence until the verifier returns PASS, unless live evidence establishes an external blocker that makes continuation impossible.',
      completion_condition: 'The handshake is complete only after the verifier returns PASS for the active challenge. A plan, partial locator, submission without PASS, or statement of completion does not close the handshake.'
    },
    viewport: {
      width_px: VIEWPORT_WIDTH,
      height_px: VIEWPORT_HEIGHT,
      character_height_px: CHARACTER_HEIGHT_PX,
      conservative_character_width_px: CONSERVATIVE_CHARACTER_WIDTH_PX,
      rows: ROWS,
      columns: COLUMNS,
      cpx: CPX
    },
    card_model: {
      logical_ordered_copies: 2,
      logical_shuffled_copies: 1,
      dense_ordered_reference_cards: referenceGroups.length,
      mixed_interleave_cards: mixedGroups.length,
      total_cards: Object.keys(cards).length,
      filenames_are_random: true,
      collection_is_mixed: true,
      interleave_rule: 'On every mixed card, counting the first visible row as 1, the ordered-array copy occupies only one parity (all odd rows or all even rows). The shuffled-array copy occupies the opposite parity.',
      placement_rule: 'Only shuffled rows on mixed cards are legal placement sources. Dense ordered-reference rows and ordered-parity rows on mixed cards are reference-only.'
    },
    answer_format: 'locator[n] = [png_filename, zero_based_array_index_in_that_png]',
    item_count: canonical.length,
    locator: Array(canonical.length).fill(null)
  };

  const active = pathsFor(sha).active;
  writeJson(active, challenge);
  console.log(`[live-ground-truth] issued ${path.basename(active)} with ${Object.keys(cards).length} random PNG cards (${referenceGroups.length} dense ordered-reference, ${mixedGroups.length} ordered+shuffled interleave)`);
  console.log(`[live-ground-truth] logical corpus = ordered x2 + shuffled x1; Cpx=${CPX}; items=${canonical.length}`);
  return challenge;
}

function parseChallengePath(challengePath) {
  const normalized = challengePath.replace(/\\/g, '/');
  const prefix = 'ChatMachines/GeminiSupervisor/live-ground-truth/reading-room/';
  if (!normalized.startsWith(prefix)) throw new Error('Challenge path is outside the reading room');
  const name = path.posix.basename(normalized);
  const match = ACTIVE_RE.exec(name);
  if (!match) throw new Error(`Not an active Live Ground Truth challenge: ${name}`);
  return { challengeCommitSha: match[1].toLowerCase() };
}

function cardInventory(challengeCommitSha) {
  const filePath = manifestPath(challengeCommitSha);
  if (!fs.existsSync(filePath)) throw new Error(`Challenge manifest not restored: ${filePath}`);
  const manifest = readJson(filePath);
  if (!manifest || manifest.challenge !== 'agents-png-locator-v2' || !manifest.cards) {
    throw new Error('Invalid challenge manifest');
  }

  const inventory = new Map();
  for (const [name, card] of Object.entries(manifest.cards)) {
    if (!CARD_NAME_RE.test(name) || !Array.isArray(card.slots) || !Array.isArray(card.placement_slots)) {
      throw new Error(`Invalid manifest card: ${name}`);
    }
    if (card.slots.length !== card.placement_slots.length) throw new Error(`Placement mask mismatch: ${name}`);

    const pngPath = path.join(readingRoom, name);
    if (!fs.existsSync(pngPath)) throw new Error(`Challenge PNG is missing: ${name}`);
    const actualSha = sha256(fs.readFileSync(pngPath));
    if (actualSha !== card.png_sha256) throw new Error(`Challenge PNG was modified: ${name}`);

    inventory.set(name, {
      slots: card.slots,
      placementSlots: card.placement_slots
    });
  }
  return { manifest, inventory };
}

function verifyLocator(locator, canonical, inventory) {
  if (!Array.isArray(locator) || locator.length !== canonical.length) return false;

  let legalPlacementCount = 0;
  for (const card of inventory.values()) {
    legalPlacementCount += card.placementSlots.filter(Boolean).length;
  }
  if (legalPlacementCount !== canonical.length) return false;

  const used = new Set();
  for (let n = 0; n < canonical.length; n++) {
    const loc = locator[n];
    if (!Array.isArray(loc) || loc.length !== 2) return false;
    const [fileName, arrayIndex] = loc;
    if (typeof fileName !== 'string' || !CARD_NAME_RE.test(fileName)) return false;
    if (!Number.isInteger(arrayIndex) || arrayIndex < 0) return false;

    const card = inventory.get(fileName);
    if (!card || arrayIndex >= card.slots.length || card.placementSlots[arrayIndex] !== true) return false;

    const unique = `${fileName}:${arrayIndex}`;
    if (used.has(unique)) return false;
    used.add(unique);

    if (!isDeepStrictEqual(card.slots[arrayIndex], canonical[n])) return false;
  }

  return used.size === canonical.length;
}

async function verify(challengePath, evaluationCommitSha) {
  const { challengeCommitSha } = parseChallengePath(challengePath);
  const evaluationSha = validateCommitSha(evaluationCommitSha);
  const resultPaths = pathsFor(evaluationSha);
  const absoluteChallenge = path.join(repoRoot, challengePath);
  if (!fs.existsSync(absoluteChallenge)) throw new Error(`Challenge file not found: ${challengePath}`);

  const full = projectAgents();
  const submitted = readJson(absoluteChallenge);
  const { manifest, inventory } = cardInventory(challengeCommitSha);
  const pass =
    manifest.source_blob_sha === full.source_blob_sha &&
    manifest.item_count === full.items.length &&
    submitted?.challenge === 'agents-png-locator-v2' &&
    submitted?.source_blob_sha === full.source_blob_sha &&
    verifyLocator(submitted.locator, full.items, inventory);

  fs.rmSync(absoluteChallenge, { force: true });
  removeGeneratedCards();

  if (pass) {
    writeJson(resultPaths.pass, {
      status: 'PASS',
      source_blob_sha: full.source_blob_sha,
      item_count: full.items.length
    });
    console.log(`[live-ground-truth] PASS ${evaluationSha}`);
    return true;
  }

  writeJson(resultPaths.failed, { status: 'FAILED' });
  await buildChallenge(evaluationSha);
  console.log(`[live-ground-truth] FAILED ${evaluationSha}; issued fresh PNG challenge`);
  return false;
}

async function issue(commitSha) {
  const request = readJson(requestPath);
  if (request['Agents.md'] !== true) throw new Error('read-request.json must contain "Agents.md": true');
  await buildChallenge(commitSha);
}

async function main() {
  const mode = process.argv[2];
  if (mode === 'issue') {
    await issue(process.argv[3]);
    return;
  }
  if (mode === 'verify') {
    const ok = await verify(process.argv[3], process.argv[4]);
    process.exitCode = ok ? 0 : 2;
    return;
  }
  throw new Error('Usage: live-ground-truth-reading-room.js issue <commit-sha> | verify <challenge-path> <evaluation-commit-sha>');
}

main().catch((error) => {
  console.error(`[live-ground-truth] ${error.stack || error.message}`);
  process.exitCode = 1;
});

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const sharp = require('sharp');

const repoRoot = path.resolve(__dirname, '../../..');
const supervisorRoot = path.join(repoRoot, 'ChatMachines/GeminiSupervisor');
const sourcePath = path.join(supervisorRoot, 'Agents.md');
const readingRoom = path.join(supervisorRoot, 'live-ground-truth/reading-room');

const WIDTH = 1440;
const HEIGHT = 900;
const CHAR_HEIGHT = 20;
const CHAR_WIDTH = 12;
const PAD_X = 24;
const PAD_Y = 20;
const FONT_SIZE = 20;
const ROWS = Math.floor((HEIGHT - (2 * PAD_Y)) / CHAR_HEIGHT);
const COLUMNS = Math.floor((WIDTH - (2 * PAD_X)) / CHAR_WIDTH);
const INDEX_PREFIX_CHARS = 8;
const ACTIVE_RE = /^Agents\.reader\.json-([0-9a-f]{40})$/i;
const CARD_RE = /^[0-9a-f]{32}\.png$/;

function entryChars(value) {
  return JSON.stringify(value).length + INDEX_PREFIX_CHARS;
}

function splitLineToRenderableItems(text, eol) {
  if (text === '') return [{ type: 'content', text: '', eol }];
  const chunks = [];
  let current = '';
  for (const ch of text) {
    const candidate = current + ch;
    const probe = { type: 'content', text: candidate, eol: '\r\n' };
    if (current && entryChars(probe) > COLUMNS) {
      chunks.push({ type: 'content', text: current, eol: '' });
      current = ch;
    } else {
      current = candidate;
    }
  }
  chunks.push({ type: 'content', text: current, eol });
  return chunks;
}

function projectAgents() {
  const text = fs.readFileSync(sourcePath, 'utf8');
  const items = [];
  const re = /(.*?)(\r\n|\n|\r|$)/g;
  let match;
  while ((match = re.exec(text)) !== null) {
    if (match[0] === '' && re.lastIndex === text.length) break;
    items.push(...splitLineToRenderableItems(match[1], match[2]));
    if (match[2] === '') break;
  }
  return items;
}

function xmlEscape(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function candidateCardSvg(value) {
  const texts = [];
  for (let row = 0; row < ROWS; row++) {
    const line = `[${row}] ${JSON.stringify(value)}`;
    const y = PAD_Y + ((row + 1) * CHAR_HEIGHT) - 3;
    texts.push(`<text x="${PAD_X}" y="${y}">${xmlEscape(line)}</text>`);
  }
  return Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">` +
    `<rect width="100%" height="100%" fill="white"/>` +
    `<g xml:space="preserve" fill="black" font-family="DejaVu Sans Mono, monospace" font-size="${FONT_SIZE}px">${texts.join('')}</g>` +
    `</svg>`,
    'utf8'
  );
}

function rowHash(raw, width, channels, row) {
  const hash = crypto.createHash('sha256');
  const top = PAD_Y + (row * CHAR_HEIGHT);
  for (let y = top; y < top + CHAR_HEIGHT; y++) {
    const start = (y * width) * channels;
    const end = start + (width * channels);
    hash.update(raw.subarray(start, end));
  }
  return hash.digest('hex');
}

function rowHasInk(raw, width, channels, row) {
  const top = PAD_Y + (row * CHAR_HEIGHT);
  for (let y = top; y < top + CHAR_HEIGHT; y++) {
    const start = (y * width) * channels;
    const end = start + (width * channels);
    for (let i = start; i < end; i++) if (raw[i] !== 255) return true;
  }
  return false;
}

async function buildCandidateMaps(canonical) {
  const byKey = new Map();
  for (const item of canonical) byKey.set(JSON.stringify(item), item);
  const unique = [...byKey.entries()];
  const maps = Array.from({ length: ROWS }, () => new Map());

  const batchSize = 16;
  for (let offset = 0; offset < unique.length; offset += batchSize) {
    const batch = unique.slice(offset, offset + batchSize);
    const results = await Promise.all(batch.map(async ([key, value]) => {
      const { data, info } = await sharp(candidateCardSvg(value))
        .removeAlpha().raw().toBuffer({ resolveWithObject: true });
      return { key, hashes: Array.from({ length: ROWS }, (_, row) => rowHash(data, info.width, info.channels, row)) };
    }));
    for (const result of results) {
      for (let row = 0; row < ROWS; row++) {
        const hash = result.hashes[row];
        const existing = maps[row].get(hash);
        if (existing && existing !== result.key) {
          throw new Error(`Pixel collision at row ${row}: ${existing} <> ${result.key}`);
        }
        maps[row].set(hash, result.key);
      }
    }
  }
  console.log(`[solver] exact-position signatures=${unique.length * ROWS}`);
  return maps;
}

async function decodeCard(filePath, maps, canonicalByKey) {
  const { data, info } = await sharp(filePath).removeAlpha().raw().toBuffer({ resolveWithObject: true });
  if (info.width !== WIDTH || info.height !== HEIGHT) {
    throw new Error(`Unexpected card dimensions ${path.basename(filePath)}: ${info.width}x${info.height}`);
  }
  const rows = [];
  for (let row = 0; row < ROWS; row++) {
    const key = maps[row].get(rowHash(data, info.width, info.channels, row));
    if (!key) {
      if (!rowHasInk(data, info.width, info.channels, row)) break;
      throw new Error(`Unmatched rendered row ${row} in ${path.basename(filePath)}`);
    }
    rows.push({ row, key, value: canonicalByKey.get(key) });
  }
  if (!rows.length) throw new Error(`No decodable rows in ${path.basename(filePath)}`);
  return rows;
}

function contiguousStart(sequenceKeys, canonicalKeys) {
  if (!sequenceKeys.length) return -1;
  const first = sequenceKeys[0];
  for (let start = 0; start + sequenceKeys.length <= canonicalKeys.length; start++) {
    if (canonicalKeys[start] !== first) continue;
    let ok = true;
    for (let j = 1; j < sequenceKeys.length; j++) {
      if (canonicalKeys[start + j] !== sequenceKeys[j]) { ok = false; break; }
    }
    if (ok) return start;
  }
  return -1;
}

function findActiveChallenge() {
  const names = fs.readdirSync(readingRoom).filter((name) => ACTIVE_RE.test(name));
  if (names.length !== 1) throw new Error(`Expected exactly one active challenge, found ${names.length}`);
  return path.join(readingRoom, names[0]);
}

async function main() {
  const activePath = findActiveChallenge();
  const challenge = JSON.parse(fs.readFileSync(activePath, 'utf8'));
  if (challenge.challenge !== 'agents-png-locator-v2') throw new Error(`Unsupported challenge ${challenge.challenge}`);

  const canonical = projectAgents();
  if (canonical.length !== challenge.item_count) throw new Error(`Canonical item count mismatch ${canonical.length} != ${challenge.item_count}`);
  const canonicalKeys = canonical.map(JSON.stringify);
  const canonicalByKey = new Map(canonical.map((item) => [JSON.stringify(item), item]));
  const maps = await buildCandidateMaps(canonical);

  const cardNames = fs.readdirSync(readingRoom).filter((name) => CARD_RE.test(name)).sort();
  if (cardNames.length !== challenge.card_model.total_cards) throw new Error(`Card count mismatch ${cardNames.length} != ${challenge.card_model.total_cards}`);

  const placement = new Map();
  let mixedCount = 0;
  let referenceCount = 0;

  for (const name of cardNames) {
    const rows = await decodeCard(path.join(readingRoom, name), maps, canonicalByKey);
    const fullStart = contiguousStart(rows.map((r) => r.key), canonicalKeys);
    if (fullStart >= 0) { referenceCount++; continue; }

    const evenRows = rows.filter((r) => r.row % 2 === 0);
    const oddRows = rows.filter((r) => r.row % 2 === 1);
    const evenStart = contiguousStart(evenRows.map((r) => r.key), canonicalKeys);
    const oddStart = contiguousStart(oddRows.map((r) => r.key), canonicalKeys);
    const evenOrdered = evenStart >= 0;
    const oddOrdered = oddStart >= 0;
    if (evenOrdered === oddOrdered) throw new Error(`Could not determine ordered parity for ${name}: even=${evenStart}, odd=${oddStart}`);

    mixedCount++;
    const shuffledRows = evenOrdered ? oddRows : evenRows;
    for (const row of shuffledRows) {
      if (!placement.has(row.key)) placement.set(row.key, []);
      placement.get(row.key).push([name, row.row]);
    }
  }

  if (mixedCount !== challenge.card_model.mixed_interleave_cards) throw new Error(`Mixed card count mismatch ${mixedCount} != ${challenge.card_model.mixed_interleave_cards}`);
  if (referenceCount !== challenge.card_model.dense_ordered_reference_cards) throw new Error(`Reference card count mismatch ${referenceCount} != ${challenge.card_model.dense_ordered_reference_cards}`);

  const locator = [];
  for (const key of canonicalKeys) {
    const queue = placement.get(key);
    if (!queue || !queue.length) throw new Error(`No unused shuffled occurrence for ${key}`);
    locator.push(queue.shift());
  }
  let leftovers = 0;
  for (const queue of placement.values()) leftovers += queue.length;
  if (leftovers !== 0) throw new Error(`Unused shuffled slots remain: ${leftovers}`);

  challenge.locator = locator;
  fs.writeFileSync(activePath, JSON.stringify(challenge) + '\n', 'utf8');
  console.log(`[solver] SOLVED ${path.basename(activePath)} items=${locator.length}, cards=${cardNames.length}`);
}

main().catch((error) => {
  console.error(`[solver] ${error.stack || error.message}`);
  process.exitCode = 1;
});

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execFileSync } = require('child_process');

const rootDir = path.resolve(__dirname, '../../..');
const depMapPath = path.join(rootDir, 'ChatMachines/GeminiSupervisor/dependency-map.json');

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function writeJson(filePath, value) {
  fs.writeFileSync(filePath, JSON.stringify(value, null, 2) + '\n', 'utf8');
}

function gitBlobSha(relPath) {
  return execFileSync('git', ['rev-parse', `HEAD:${relPath}`], {
    cwd: rootDir,
    encoding: 'utf8'
  }).trim();
}

function gitLastCommitSha(relPath) {
  return execFileSync('git', ['log', '-1', '--format=%H', '--', relPath], {
    cwd: rootDir,
    encoding: 'utf8'
  }).trim();
}

function gitBlobShaForBytes(bytes) {
  const header = Buffer.from(`blob ${bytes.length}\0`, 'utf8');
  return crypto.createHash('sha1').update(header).update(bytes).digest('hex');
}

function sourceToOrderedItems(text) {
  const items = [];
  let cursor = 0;
  let lineNumber = 1;

  if (text.length === 0) {
    return [{ type: 'content', line_number: 1, text: '', eol: '' }];
  }

  while (cursor < text.length) {
    const newline = text.indexOf('\n', cursor);
    let end;
    let eol;

    if (newline === -1) {
      end = text.length;
      eol = '';
    } else if (newline > cursor && text[newline - 1] === '\r') {
      end = newline - 1;
      eol = '\r\n';
    } else {
      end = newline;
      eol = '\n';
    }

    items.push({
      type: 'content',
      line_number: lineNumber++,
      text: text.slice(cursor, end),
      eol
    });

    if (newline === -1) {
      cursor = text.length;
    } else {
      cursor = newline + 1;
    }
  }

  return items;
}

function buildReader(docId, entry, sourceText, sourceBlobSha, sourceCommitSha) {
  return {
    doc_id: docId,
    canonical_path: entry.canonical_path,
    format: entry.format,
    source_provenance: {
      source_blob_sha: sourceBlobSha,
      source_commit_sha: sourceCommitSha
    },
    items: sourceToOrderedItems(sourceText)
  };
}

function syncStableReaders() {
  const depMap = readJson(depMapPath);
  const registry = depMap.truth_readable_registry;

  if (!registry || typeof registry !== 'object' || Array.isArray(registry)) {
    throw new Error('dependency-map.json.truth_readable_registry must be an object');
  }

  let changed = 0;

  for (const [docId, entry] of Object.entries(registry)) {
    const sourceAbs = path.join(rootDir, entry.canonical_path);
    const readerAbs = path.join(rootDir, entry.stable_reader_path);

    if (!fs.existsSync(sourceAbs)) {
      throw new Error(`Canonical truth-readable document is missing: ${entry.canonical_path}`);
    }

    const sourceBlobSha = gitBlobSha(entry.canonical_path);
    const sourceCommitSha = gitLastCommitSha(entry.canonical_path);

    let readerMatches = false;
    if (fs.existsSync(readerAbs) && entry.reader_blob_sha) {
      const currentReaderBytes = fs.readFileSync(readerAbs);
      const currentReaderBlobSha = gitBlobShaForBytes(currentReaderBytes);
      readerMatches = currentReaderBlobSha === entry.reader_blob_sha;
    }

    const provenanceMatches =
      entry.source_blob_sha === sourceBlobSha &&
      entry.source_commit_sha === sourceCommitSha;

    if (readerMatches && provenanceMatches) {
      console.log(`[sync-stable-readers] unchanged: ${docId}`);
      continue;
    }

    const sourceText = fs.readFileSync(sourceAbs, 'utf8');
    const reader = buildReader(docId, entry, sourceText, sourceBlobSha, sourceCommitSha);
    const readerText = JSON.stringify(reader, null, 2) + '\n';
    const readerBytes = Buffer.from(readerText, 'utf8');
    const readerBlobSha = gitBlobShaForBytes(readerBytes);

    fs.mkdirSync(path.dirname(readerAbs), { recursive: true });
    fs.writeFileSync(readerAbs, readerBytes);

    entry.source_blob_sha = sourceBlobSha;
    entry.source_commit_sha = sourceCommitSha;
    entry.reader_blob_sha = readerBlobSha;
    entry.item_count = reader.items.length;
    entry.last_synced_at = new Date().toISOString();

    changed++;
    console.log(`[sync-stable-readers] rebuilt: ${docId}`);
  }

  if (changed > 0) {
    writeJson(depMapPath, depMap);
  }

  console.log(`[sync-stable-readers] changed_readers=${changed}`);
  return changed;
}

if (require.main === module) {
  syncStableReaders();
}

module.exports = {
  syncStableReaders,
  sourceToOrderedItems,
  gitBlobShaForBytes
};

